import{_ as a,C as e,c as t,o as i,j as n,b as o,a0 as r,a as l,w as s,G as c,a1 as d}from"./chunks/framework.DKRgXLPU.js";const p=JSON.parse('{"title":"Capacitación técnica vs. capacitación de flujo","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/the-zone/technical-vs-flow.md","filePath":"es/education/the-zone/technical-vs-flow.md"}');const m=a({name:"es/education/the-zone/technical-vs-flow.md"},[["render",function(a,p,m,u,h,b){const g=e("Mermaid");return i(),t("div",null,[p[1]||(p[1]=n("h1",{id:"capacitacion-tecnica-vs-capacitacion-de-flujo",tabindex:"-1"},[l("Capacitación técnica vs. capacitación de flujo "),n("a",{class:"header-anchor",href:"#capacitacion-tecnica-vs-capacitacion-de-flujo","aria-label":'Permalink to "Capacitación técnica vs. capacitación de flujo"'},"​")],-1)),p[2]||(p[2]=n("p",null,"Comprender la diferencia entre el entrenamiento técnico y el entrenamiento de flujo es esencial para el desarrollo de élite. Ambos son necesarios, pero tienen propósitos diferentes y requieren enfoques distintos.",-1)),p[3]||(p[3]=n("div",{class:"tip custom-block"},[n("p",{class:"custom-block-title"},"El principio fundamental"),n("p",null,[n("strong",null,"No se puede entrenar a un principiante como a un experto"),l(" (carecen de vías neuronales), y "),n("strong",null,"no se puede entrenar a un experto como a un principiante"),l(" (un alto volumen técnico provoca un pensamiento excesivo).")])],-1)),(i(),o(d,null,{default:s(()=>[c(g,{id:"mermaid-11",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20A%5BPrincipiante%20%3Cbr%2F%3E%2090%25%20Tecnolog%C3%ADa%5D%20--%3E%20B%5BIntermedio%20%3Cbr%2F%3E%2070%25%20Tecnolog%C3%ADa%5D%0A%20%20%20%20B%20--%3E%20C%5BAvanzado%20%3Cbr%2F%3E%2050%25%20Tecnolog%C3%ADa%5D%0A%20%20%20%20C%20--%3E%20D%5BExperto%20%3Cbr%2F%3E%2020%25%20Tecnolog%C3%ADa%5D%0A%0A%20%20%20%20A2%5B10%25%20Mental%5D%20--%3E%20B2%5B30%25%20Mental%5D%0A%20%20%20%20B2%20--%3E%20C2%5B50%25%20Mental%5D%0A%20%20%20%20C2%20--%3E%20D2%5B80%25%20Mental%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23ffcdd2%0A%20%20%20%20style%20B%20fill%3A%23ffccbc%0A%20%20%20%20style%20C%20fill%3A%23fff9c4%0A%20%20%20%20style%20D%20fill%3A%23c8e6c9%0A%20%20%20%20style%20D2%20fill%3A%23a5d6a7%0A"})]),fallback:s(()=>[...p[0]||(p[0]=[l(" Loading... ",-1)])]),_:1})),p[4]||(p[4]=r('<h2 id="dos-tipos-de-entrenamiento" tabindex="-1">Dos tipos de entrenamiento <a class="header-anchor" href="#dos-tipos-de-entrenamiento" aria-label="Permalink to &quot;Dos tipos de entrenamiento&quot;">​</a></h2><div class="info custom-block"><p class="custom-block-title">Capacitación técnica (aprendizaje explícito)</p><p><strong>Enfoque:</strong> Mecánica y forma <strong>Atención:</strong> Movimientos corporales conscientes <strong>Método:</strong> Desglosar habilidades, práctica repetitiva <strong>Ideal para:</strong> Aprender nuevas habilidades, corregir malos hábitos, construir bases.</p><p><strong>Ejemplo:</strong> Practicar el punto de lanzamiento 50 veces con análisis de video</p></div><div class="info custom-block"><p class="custom-block-title">Entrenamiento de flujo (aprendizaje implícito)</p><p><strong>Enfoque:</strong> Resultados, no mecánica <strong>Atención:</strong> Dejar que el subconsciente tome el control <strong>Método:</strong> Práctica variada, similar a un juego, visualización. <strong>Ideal para:</strong> Preparación para competiciones, desarrollo de confianza, máximo rendimiento.</p><p><strong>Ejemplo:</strong> Jugar partidos de práctica con presión, concentrándose solo en los objetivos</p></div><h2 id="el-modelo-de-inversion-dinamica" tabindex="-1">El modelo de inversión dinámica <a class="header-anchor" href="#el-modelo-de-inversion-dinamica" aria-label="Permalink to &quot;El modelo de inversión dinámica&quot;">​</a></h2><p>Una proporción correcta de entrenamiento está inversamente relacionada con la competencia técnica. A medida que se domina la técnica, el entrenamiento mental cobra mayor importancia, no menor.</p><h3 id="_1-principiante-etapa-cognitiva" tabindex="-1">1. Principiante (Etapa cognitiva) <a class="header-anchor" href="#_1-principiante-etapa-cognitiva" aria-label="Permalink to &quot;1. Principiante (Etapa cognitiva)&quot;">​</a></h3><ul><li>Piensas conscientemente en <em>qué</em> hacer</li><li>Los movimientos se sienten incómodos y requieren esfuerzo.</li><li>El cerebro está completamente saturado de mecánica.</li><li><strong>Relación:</strong> 90% Técnico / 10% Mental</li><li><strong>Enfoque mental:</strong> Disfrute, enfoque externo (mirar el objetivo), no visualización compleja</li></ul><h3 id="_2-intermedio-etapa-asociativa" tabindex="-1">2. Intermedio (Etapa asociativa) <a class="header-anchor" href="#_2-intermedio-etapa-asociativa" aria-label="Permalink to &quot;2. Intermedio (Etapa asociativa)&quot;">​</a></h3><ul><li>Refinas la habilidad con menos pensamiento consciente.</li><li>Los movimientos se vuelven más suaves, los errores disminuyen.</li><li>Empiezas a detectar tus propios errores</li><li><strong>Ratio:</strong> 70% Técnico / 30% Mental</li><li><strong>Enfoque mental:</strong> Desarrollar tu rutina previa al rendimiento (PPR)</li></ul><h3 id="_3-avanzado-umbral-de-autonomia" tabindex="-1">3. Avanzado (Umbral de Autonomía) <a class="header-anchor" href="#_3-avanzado-umbral-de-autonomia" aria-label="Permalink to &quot;3. Avanzado (Umbral de Autonomía)&quot;">​</a></h3><ul><li>La habilidad está en gran parte automatizada.</li><li>Tu autoimagen a menudo va por detrás de tu capacidad física</li><li>La formación se centra en la simulación de presión.</li><li><strong>Relación:</strong> 50% Técnico / 50% Mental</li><li><strong>Enfoque mental:</strong> Visualización, autoimagen, control de la ansiedad.</li></ul><h3 id="_4-experto-etapa-autonoma" tabindex="-1">4. Experto (Etapa Autónoma) <a class="header-anchor" href="#_4-experto-etapa-autonoma" aria-label="Permalink to &quot;4. Experto (Etapa Autónoma)&quot;">​</a></h3><ul><li>Las habilidades técnicas son totalmente subconscientes</li><li>La atención consciente a la mecánica altera el rendimiento</li><li>El volumen de mantenimiento es todo lo que necesitas técnicamente</li><li><strong>Ratio:</strong> 20% Técnico / 80% Mental</li><li><strong>Enfoque mental:</strong> Estado de flujo, estrategia, aquietar la mente.</li></ul><h2 id="la-tabla-de-progresion" tabindex="-1">La tabla de progresión <a class="header-anchor" href="#la-tabla-de-progresion" aria-label="Permalink to &quot;La tabla de progresión&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nivel</th><th>Tecnología: Mental</th><th>Objetivo principal</th></tr></thead><tbody><tr><td>Principiante</td><td>90:10</td><td>Construye la máquina</td></tr><tr><td>Intermedio</td><td>70:30</td><td>Estabilizar la habilidad</td></tr><tr><td>Avanzado</td><td>50:50</td><td>Confía en la máquina</td></tr><tr><td>Experto</td><td>20:80</td><td>Libertad de Ejecución</td></tr></tbody></table><h2 id="la-trampa-del-experto" tabindex="-1">La trampa del experto <a class="header-anchor" href="#la-trampa-del-experto" aria-label="Permalink to &quot;La trampa del experto&quot;">​</a></h2><p>Para los jugadores avanzados y expertos, volver a un enfoque técnico elevado es peligroso.</p><p><strong>El problema:</strong> Cuando automatizas una habilidad, pero la monitorizas conscientemente durante la competición, activas la mente consciente y anulas el subconsciente. Esto provoca ansiedad y ahogo.</p><p><strong>La ciencia:</strong> El volumen necesario para mantener una habilidad es significativamente menor (a menudo entre un tercio y un noveno) que el necesario para desarrollarla. Los expertos necesitan un trabajo técnico mínimo para conservar su toque.</p><p><strong>Ejemplo de élite:</strong> Campeones como Philippe Quintais y Dylan Rocher se centran mucho en escenarios tácticos y momentos críticos en lugar de ejercicios mecánicos.</p><p>Señales de que estás pensando demasiado en la técnica:</p><ul><li>Parálisis por análisis</li><li>Rendimiento inconsistente a pesar de una buena técnica</li><li>Peores resultados en la competición que en la práctica</li><li>Sentirse &quot;mecánico&quot; en lugar de fluido</li></ul><h2 id="comparacion-de-metodos-de-entrenamiento" tabindex="-1">Comparación de métodos de entrenamiento <a class="header-anchor" href="#comparacion-de-metodos-de-entrenamiento" aria-label="Permalink to &quot;Comparación de métodos de entrenamiento&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspecto</th><th>Capacitación técnica</th><th>Entrenamiento de flujo</th></tr></thead><tbody><tr><td><strong>Tipo de práctica</strong></td><td>Bloqueado (la misma habilidad repetidamente)</td><td>Aleatorio (habilidades variadas)</td></tr><tr><td><strong>Comentario</strong></td><td>Inmediato, detallado</td><td>Retrasado, centrado en los resultados</td></tr><tr><td><strong>Ambiente</strong></td><td>Controlado, predecible</td><td>Variable, similar a un juego</td></tr><tr><td><strong>Estado mental</strong></td><td>Analítico, consciente</td><td>Intuitivo, automático</td></tr><tr><td><strong>Mejor momento</strong></td><td>Fuera de temporada, desarrollo de habilidades</td><td>Precompetición, mantenimiento</td></tr></tbody></table><h2 id="practica-bloqueada-vs-practica-aleatoria" tabindex="-1">Práctica bloqueada vs. práctica aleatoria <a class="header-anchor" href="#practica-bloqueada-vs-practica-aleatoria" aria-label="Permalink to &quot;Práctica bloqueada vs. práctica aleatoria&quot;">​</a></h2><p><strong>Práctica bloqueada:</strong> Repite el mismo lanzamiento 20 veces</p><ul><li>Se siente productivo (se nota una mejora rápida)</li><li>Bueno para el aprendizaje inicial</li><li>Pobre para la retención a largo plazo</li></ul><p><strong>Práctica aleatoria:</strong> Varía la distancia, el objetivo y el tipo de lanzamiento.</p><ul><li>Se siente más difícil (más errores)</li><li>Mejor para la transferencia de la competencia</li><li>Desarrolla la adaptabilidad y la toma de decisiones.</li></ul><h2 id="directrices-practicas" tabindex="-1">Directrices prácticas <a class="header-anchor" href="#directrices-practicas" aria-label="Permalink to &quot;Directrices prácticas&quot;">​</a></h2><h3 id="para-sesiones-tecnicas" tabindex="-1">Para sesiones técnicas <a class="header-anchor" href="#para-sesiones-tecnicas" aria-label="Permalink to &quot;Para sesiones técnicas&quot;">​</a></h3><ol><li>Concéntrese en UN aspecto a la vez</li><li>Utilice el análisis de vídeo</li><li>Obtenga comentarios de un entrenador o compañero de entrenamiento</li><li>Acepta que al principio te sentirás incómodo</li><li>Mantenga las sesiones más cortas (calidad sobre cantidad)</li></ol><h3 id="para-sesiones-de-flujo" tabindex="-1">Para sesiones de flujo <a class="header-anchor" href="#para-sesiones-de-flujo" aria-label="Permalink to &quot;Para sesiones de flujo&quot;">​</a></h3><ol><li>Crear una presión similar a la del juego</li><li>Concéntrese en el objetivo, no en su cuerpo.</li><li>Utilice su rutina previa a la inyección de manera constante</li><li>No analizar durante la sesión</li><li>Confía en tu entrenamiento</li></ol><h2 id="el-desafio-de-la-integracion" tabindex="-1">El desafío de la integración <a class="header-anchor" href="#el-desafio-de-la-integracion" aria-label="Permalink to &quot;El desafío de la integración&quot;">​</a></h2><p>La verdadera habilidad es saber cuándo utilizar cada modo:</p><p><strong>Durante un partido de competición:</strong></p><ul><li>Pensamiento técnico: NUNCA durante la ejecución</li><li>Modo de flujo: SIEMPRE al lanzar</li></ul><p><strong>Durante la práctica:</strong></p><ul><li>Sesiones técnicas: programadas, enfoque específico</li><li>Sesiones de flujo: Simulación de juego, práctica de presión</li></ul><h2 id="ejemplo-de-saldo-semanal" tabindex="-1">Ejemplo de saldo semanal <a class="header-anchor" href="#ejemplo-de-saldo-semanal" aria-label="Permalink to &quot;Ejemplo de saldo semanal&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Día</th><th>Tipo de sesión</th><th>Enfocar</th></tr></thead><tbody><tr><td>Lunes</td><td>Técnico</td><td>Precisión de puntería</td></tr><tr><td>Martes</td><td>Técnico</td><td>Precisión de disparo</td></tr><tr><td>Miércoles</td><td>Fluir</td><td>Entrenamiento mental, visualización</td></tr><tr><td>Jueves</td><td>Mezclado</td><td>Escenarios de juego con enfoque en el flujo</td></tr><tr><td>Viernes</td><td>Técnico</td><td>Área de debilidad</td></tr><tr><td>Sábado</td><td>Fluir</td><td>Match play, simulación de competición</td></tr><tr><td>Domingo</td><td>Descansar</td><td>Recuperación, reflexión</td></tr></tbody></table><h2 id="resumen-reglas-de-equilibrio-en-el-entrenamiento" tabindex="-1">Resumen: Reglas de equilibrio en el entrenamiento <a class="header-anchor" href="#resumen-reglas-de-equilibrio-en-el-entrenamiento" aria-label="Permalink to &quot;Resumen: Reglas de equilibrio en el entrenamiento&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Regla n.° 1: Adaptar el entrenamiento al nivel</p><p><strong>Principiantes (90/10):</strong> Construye la máquina: céntrate en la técnica <strong>Intermedio (70/30):</strong> Estabilizar la habilidad - agregar trabajo mental <strong>Avanzado (50/50):</strong> Confía en la máquina: equilibra ambos <strong>Experto (20/80):</strong> Libertad de ejecución, principalmente mental</p></div><div class="tip custom-block"><p class="custom-block-title">Regla n.° 2: Práctica bloqueada vs. práctica aleatoria</p><p><strong>Práctica bloqueada</strong> (mismo lanzamiento repetidamente): bueno para el aprendizaje inicial, malo para la retención <strong>Práctica aleatoria</strong> (lanzamientos variados): más difícil en la práctica, mejor en la competición</p></div><div class="tip custom-block"><p class="custom-block-title">Regla n.° 3: La trampa del experto</p><p><strong>Para los expertos:</strong> Un alto volumen técnico provoca pensamientos excesivos y ahogos. <strong>Solución:</strong> Mínimo mantenimiento técnico, máximo entrenamiento mental</p></div><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>No se puede entrenar a un principiante como a un experto (carecen de las vías neuronales para el trabajo mental), ni se puede entrenar a un experto como a un principiante (un alto volumen técnico provoca agotamiento y pensamiento excesivo).</p></blockquote><p>El paso de la técnica al flujo requiere una inversión estratégica. Adapta tu entrenamiento a tu etapa de desarrollo.</p>',49))])}]]);export{p as __pageData,m as default};
